  'vault.subtitle': 'Güvenli, tamamen yerel sır deposu — işletim sistemi anahtarlığınızla şifrelenir.',
  'vault.explainer':
    'Kasa bir dosya değildir ve .env dosyanızla hiçbir ilgisi yoktur. Yalnızca bu makinede duran, şifreli bir anahtar/değer deposudur — kayıtlar bir depoya bağlanabilir (ya da genel tutulabilir), ama asla depoya yazılmaz, commit’lenmez ve push’lanmaz. Sırlarınızı el altında tutmak için kullanın: değeri açığa çıkarın, kopyalayın ya da gerçekten ihtiyacınız olan yere yapıştırmak için “.env olarak kopyala” deyin.',
