  'attrs.driverStale': 'dönüştürücü 4.39 öncesine ait',
  'attrs.driverStaleHint': 'Bu dönüştürücü, 4.38 dahil önceki sürümlerin uygulamanın eski adıyla birlikte gönderdiği dönüştürücüdür. Uygulama bu tür sürücüleri kendiliğinden güncel dönüştürücüsüne yönlendirir; bu ise yönlendirilemedi: bir AppImage yolu her açılışta değişir ya da yapılandırma yazılamadı. Eski kurulum yerinde durmadıkça bu dosyaların farkları başarısız olur. Kaldırın, ardından sürücüyü aşağıdaki önerilerden yeniden ekleyin.',
