  'keychain.tokenStoreUnreadable': 'Yalnızca GitHuttBr’yu kapatana kadar saklanır: kayıtlı belirteçleriniz okunamadı. Anahtarlığın kilidini açıp yeniden deneyin.',
  'keychain.storeUnreadable': 'GitHuttBr kayıtlı belirteçlerinizi okuyamadı — anahtarlık kilitliydi ya da erişim reddedildi. Belirteçlere dokunulmadı. Anahtarlığın kilidini açıp yeniden deneyin; bu arada eklediğiniz belirteçler yalnızca uygulamayı kapatana kadar saklanır.',
  'keychain.weakBackend': 'Çalışan bir anahtarlık yok (GNOME Keyring veya KWallet), bu yüzden sistem temel depolamayı kullanıyor; bu depolama verileri korumak yerine yalnızca sabit bir parolayla karıştırır. Daha önce kaydettiğiniz belirteçler okunmaya devam eder, ancak yenileri yalnızca uygulamayı kapatana kadar tutulur; Kasa oraya kaydetmeyi sürdürür. Bir anahtarlık kurun veya kilidini açın, ardından GitHuttBr\'yu yeniden başlatın.',
