  'gitError.workflowScopeOAuth': "GitHub push'u reddetti: {file} workflow'unu değiştiriyor ve bu oturumda `workflow` kapsamı yok. GitHub CLI oturumu için `gh auth refresh -h github.com -s workflow` çalıştırın ve yeniden gönderin.",
  'gitError.workflowScopeToken': "GitHub push'u reddetti: {file} workflow'unu değiştiriyor ve kişisel erişim belirteci workflow düzenleyemiyor. Ona `workflow` kapsamını (klasik belirteç) ya da Workflows: Read and write (fine-grained) iznini verin ve yeniden gönderin.",
  'gitError.fileTooLarge': "GitHub 100 MB'tan büyük dosyaları reddeder ve {file} bunlardan biri. Gönderilen commit'lerden çıkarın ya da Git LFS ile izleyin.",
  'gitError.fileTooLargeAny': "GitHub 100 MB'tan büyük dosyaları reddeder ve push böyle bir dosya içeriyor. Gönderilen commit'lerden çıkarın ya da Git LFS ile izleyin.",
  'gitError.protectedBranch': "Sunucu bu dalı koruyor ve push'u reddetti. Yeni bir dala gönderin ve bir pull request açın.",
  'gitError.noCredential': "git'in {host} için kimlik bilgisi yok. Ayarlar → Bağlı hesaplar'da bir hesap bağlayın ya da git'in credential helper'ında oturum açın, sonra yeniden deneyin.",
  'gitError.boundProfileNoCredential': "Bu deponun bağlı olduğu “{profile}” profiline {host} için bir {provider} hesabı bağlı değil. O profile geçip Ayarlar → Bağlı hesaplar'dan oturum açın ya da oraya bir token ekleyin.",
  'gitError.githubNoCredentialGhMissing': "Bu profile {host} için bağlı bir GitHub hesabı yok. GitHub CLI (gh) kurulu değil: Ayarlar → Bağlı hesaplar'dan bir kişisel erişim token'ı ekleyin ya da gh'yi kurup `gh auth login` çalıştırın ve oradan oturum açın.",
  'gitError.githubNoCredentialGhSignedOut': "Bu profile {host} için bağlı bir GitHub hesabı yok. GitHub CLI (gh) kurulu ama oturum açılmamış: `gh auth login` çalıştırın, ardından Ayarlar → Bağlı hesaplar'dan oturum açın ya da oraya bir kişisel erişim token'ı ekleyin.",
  'gitError.githubNoCredentialGhUnknown': "Bu profile {host} için bağlı bir GitHub hesabı yok. GitHub CLI (gh) kontrolü zaman aşımına uğradı — çevrimdışı olabilirsiniz. Ayarlar → Bağlı hesaplar'dan oturum açın ya da oraya bir kişisel erişim token'ı ekleyin.",
  'gitError.githubNoCredentialGhSignedIn': "Bu profile {host} için bağlı bir GitHub hesabı yok. GitHub CLI (gh) oturumu açık: o hesabı bu profile bağlamak için Ayarlar → Bağlı hesaplar'dan oturum açın ya da oraya bir kişisel erişim token'ı ekleyin.",
  'gitError.noLinkedAccount': "Bu profile {host} için bağlı bir {provider} hesabı yok. git'in credential helper'ında tutulan bir oturumu bağlamak için Ayarlar → Bağlı hesaplar'dan oturum açın ya da oraya bir token ekleyin.",
  'gitError.noLinkedAccountAnyHost': "Bu profile bağlı bir {provider} hesabı yok. git'in credential helper'ında tutulan bir oturumu bağlamak için Ayarlar → Bağlı hesaplar'dan oturum açın ya da oraya bir token ekleyin.",
  'gitError.permissionDenied': 'Sunucu yazma erişimini reddetti: kullanılan hesap buraya yazamıyor ya da belirtecinin süresi doldu. Etkin profili, hesabın erişimini ve belirteci kontrol edin.',
